import{_ as s,C as r,o,c as n,j as t,a,E as d,a2 as h}from"./chunks/framework.BFMro0Mr.js";const y=JSON.parse('{"title":"ApiPresenter pipeline","description":"The exact order of steps in Nette API ApiPresenter::run(), from CORS and endpoint lookup to authorization, handler, output check and logging, with each exit code.","frontmatter":{"title":"ApiPresenter pipeline","description":"The exact order of steps in Nette API ApiPresenter::run(), from CORS and endpoint lookup to authorization, handler, output check and logging, with each exit code."},"headers":[],"relativePath":"guide/presenter.md","filePath":"guide/presenter.md","lastUpdated":1793455816000}'),p={name:"guide/presenter.md"};function l(c,e,k,u,g,m){const i=r("Diagram");return o(),n("div",null,[e[0]||(e[0]=t("h1",{id:"apipresenter-pipeline",tabindex:"-1"},[a("ApiPresenter pipeline "),t("a",{class:"header-anchor",href:"#apipresenter-pipeline","aria-label":'Permalink to "ApiPresenter pipeline"'},"​")],-1)),e[1]||(e[1]=t("p",null,[t("code",null,"Tomaj\\NetteApi\\Presenters\\ApiPresenter::run()"),a(" is the whole request in one method. This page follows it step by step, from the source of 3.x.")],-1)),d(i,{name:"presenter-1",alt:"run() sends CORS headers, finds the endpoint, checks the rate limit, reads params, checks authorization, reports param errors, calls the handler, validates the output and logs the request; exits with 404, 429, 401, 400 and 500"}),e[2]||(e[2]=h(`<table tabindex="0"><thead><tr><th>Step</th><th>Code</th><th>Exit</th></tr></thead><tbody><tr><td>1. CORS headers</td><td><code>sendCorsHeaders()</code></td><td></td></tr><tr><td>2. Endpoint</td><td><code>$this-&gt;apiDecider-&gt;getApi(...)</code></td><td><code>404</code> through <code>DefaultHandler</code> and <code>handleNotFound()</code></td></tr><tr><td>3. Rate limit</td><td><code>checkRateLimit($rateLimit)</code></td><td><code>429</code>, not logged</td></tr><tr><td>4. Read params</td><td><code>new ParamsProcessor($handler-&gt;params())</code></td><td></td></tr><tr><td>5. Authorization</td><td><code>checkAuth($authorization, $params)</code></td><td><code>401</code> or <code>500</code>, not logged</td></tr><tr><td>6. Param errors</td><td><code>errorHandler-&gt;handleInputParams()</code></td><td><code>400</code>, not logged</td></tr><tr><td>7. Handler</td><td><code>$handler-&gt;handle($params)</code></td><td>exception: <code>500</code></td></tr><tr><td>8. Output check</td><td><code>$output-&gt;validate($response)</code></td><td>no match: <code>500</code></td></tr><tr><td>9. Logger</td><td><code>logRequest()</code></td><td></td></tr></tbody></table><h2 id="_1-cors" tabindex="-1">1. CORS <a class="header-anchor" href="#_1-cors" aria-label="Permalink to &quot;1. CORS&quot;">​</a></h2><p>Headers go out first, so even a <code>404</code> or <code>401</code> carries them and the browser can read the error. <code>setCorsAllowedOrigins()</code> takes precedence over <code>setCorsHeader()</code>. See <a href="/nette-api/pr-preview/pr-238/guide/cors.html">CORS</a>.</p><h2 id="_2-endpoint-lookup" tabindex="-1">2. Endpoint lookup <a class="header-anchor" href="#_2-endpoint-lookup" aria-label="Permalink to &quot;2. Endpoint lookup&quot;">​</a></h2><p>The method and the <code>version</code>, <code>package</code> and <code>apiAction</code> route parameters go to <code>ApiDecider</code>. An unknown URL gets <code>DefaultHandler</code>, which goes through the remaining steps; instead of calling it the presenter asks the error handler&#39;s <code>handleNotFound()</code> for the <code>404</code>, which is logged. See <a href="/nette-api/pr-preview/pr-238/guide/api-decider.html">ApiDecider and endpoints</a>.</p><h2 id="_3-rate-limit" tabindex="-1">3. Rate limit <a class="header-anchor" href="#_3-rate-limit" aria-label="Permalink to &quot;3. Rate limit&quot;">​</a></h2><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$results </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $rateLimit</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">consume</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">new</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> RateLimitContext</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">($api, $request, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">RateLimitStage</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">BeforeAuthorization</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, $ip));</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// adds RateLimit-Policy and RateLimit for every result</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/* a result is not accepted */</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // 429, Retry-After, your error response or errorHandler-&gt;handleRateLimit()</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Before authorization, so failed logins count. After a successful authorization (step 5) the presenter calls <code>consume()</code> again with <code>RateLimitStage::AfterAuthorization</code> and the identity, for the policies keyed by <code>identity</code>. See <a href="/nette-api/pr-preview/pr-238/guide/rate-limit.html">Rate limiting</a>.</p><h2 id="_4-params-are-read" tabindex="-1">4. Params are read <a class="header-anchor" href="#_4-params-are-read" aria-label="Permalink to &quot;4. Params are read&quot;">​</a></h2><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$paramsProcessor </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> ParamsProcessor</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">($handler</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">params</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">());</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$params </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $paramsProcessor</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">isError</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $paramsProcessor</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getValues</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre></div><p>Every param is read and validated. With an error, <code>$params</code> is empty and the error waits for step 6.</p><h2 id="_5-authorization" tabindex="-1">5. Authorization <a class="header-anchor" href="#_5-authorization" aria-label="Permalink to &quot;5. Authorization&quot;">​</a></h2><p><code>authorized()</code> returning <code>false</code> goes to <code>handleAuthorization()</code>: <code>401</code> with <code>getErrorMessage()</code>. An exception goes to <code>handleAuthorizationException()</code>: <code>500</code> with the exception message, so do not put secrets in it. See <a href="/nette-api/pr-preview/pr-238/guide/authorization.html">Authorization</a>.</p><h2 id="_6-param-errors" tabindex="-1">6. Param errors <a class="header-anchor" href="#_6-param-errors" aria-label="Permalink to &quot;6. Param errors&quot;">​</a></h2><p>Only now, after authorization, a wrong input answers <code>400</code>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;status&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;error&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;wrong input&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;detail&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;page&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Field is required&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]}}</span></span></code></pre></div><p><code>detail</code> is shown unless the configurator hides it, as <code>EnvConfigurator</code> does in production. See <a href="/nette-api/pr-preview/pr-238/guide/params.html">Input params</a>.</p><h2 id="_7-the-handler" tabindex="-1">7. The handler <a class="header-anchor" href="#_7-the-handler" aria-label="Permalink to &quot;7. The handler&quot;">​</a></h2><p><code>handle($params)</code> runs inside <code>try</code>. Any <code>Throwable</code> goes to <code>ErrorHandlerInterface::handle()</code>, which logs it to Tracy and answers <code>500</code>. See <a href="/nette-api/pr-preview/pr-238/guide/errors.html">Error handling</a>.</p><h2 id="_8-output-check" tabindex="-1">8. Output check <a class="header-anchor" href="#_8-output-check" aria-label="Permalink to &quot;8. Output check&quot;">​</a></h2><p>When <code>ConfiguratorInterface::validateSchema()</code> is true, the response is compared with each of <code>outputs()</code>; <strong>the first match is enough</strong>. No match goes to <code>handleSchema()</code> and <code>500</code>. An empty <code>outputs()</code> is not checked. Every code your handler returns needs an output, which the <a href="/nette-api/pr-preview/pr-238/examples/pagination.html">pagination example</a> shows for <code>400</code> and <code>404</code>. See <a href="/nette-api/pr-preview/pr-238/guide/outputs.html">Outputs</a>.</p><h2 id="_9-logging" tabindex="-1">9. Logging <a class="header-anchor" href="#_9-logging" aria-label="Permalink to &quot;9. Logging&quot;">​</a></h2><p>If the container has an <code>ApiLoggerInterface</code>, the request is logged with its final code and time. Secret headers and query parameters are masked first, by default as <code>***</code> (<code>setMaskedLogHeaders()</code>, <code>setMaskedLogQueryParams()</code>, <code>setLogMasking()</code>, see <a href="/nette-api/pr-preview/pr-238/guide/logging.html#presenter-methods">the methods</a>). Steps 3, 5 and 6 returned already, so <code>429</code>, <code>401</code> and <code>400</code> are not logged in 3.x. See <a href="/nette-api/pr-preview/pr-238/guide/logging.html">Logging</a>.</p><h2 id="configuring-the-presenter" tabindex="-1">Configuring the presenter <a class="header-anchor" href="#configuring-the-presenter" aria-label="Permalink to &quot;Configuring the presenter&quot;">​</a></h2><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">services</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">	apiPresenter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">		factory</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Tomaj\\NetteApi\\Presenters\\ApiPresenter</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">		setup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">			- </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">setCorsAllowedOrigins([&#39;https://app.example.com&#39;])</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">			- </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">addMaskedLogHeader(X-Session)</span></span></code></pre></div><p>This is the one <code>apiPresenter</code> service from <a href="/nette-api/pr-preview/pr-238/guide/getting-started.html#_3-register-the-services">Getting started</a>: add these <code>setup:</code> lines to it, or put the block in another config file under the same name and Nette merges the two. Do not register a second <code>ApiPresenter</code> service; two of them fail with &quot;Multiple services of type Tomaj\\NetteApi\\Presenters\\ApiPresenter found&quot;.</p><p>The class is <code>final</code>. Change its behaviour through these setters and through the services it takes from the container: <code>ErrorHandlerInterface</code>, <code>ConfiguratorInterface</code>, <code>ApiLoggerInterface</code> and <code>IpDetectorInterface</code>.</p><h2 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h2><h3 id="why-does-wrong-input-with-a-wrong-token-answer-401" tabindex="-1">Why does wrong input with a wrong token answer 401? <a class="header-anchor" href="#why-does-wrong-input-with-a-wrong-token-answer-401" aria-label="Permalink to &quot;Why does wrong input with a wrong token answer 401?&quot;">​</a></h3><p>Authorization (step 5) runs before param errors (step 6).</p><h3 id="why-is-my-400-turned-into-500" tabindex="-1">Why is my 400 turned into 500? <a class="header-anchor" href="#why-is-my-400-turned-into-500" aria-label="Permalink to &quot;Why is my 400 turned into 500?&quot;">​</a></h3><p>The handler returned <code>400</code> but no output with code <code>400</code> matches. Add one, or turn validation off in production.</p><h3 id="does-the-rate-limit-see-the-authorized-user" tabindex="-1">Does the rate limit see the authorized user? <a class="header-anchor" href="#does-the-rate-limit-see-the-authorized-user" aria-label="Permalink to &quot;Does the rate limit see the authorized user?&quot;">​</a></h3><p>Yes, a policy with <code>key: identity</code> runs after the authorization and counts per identity of an <code>AuthorizationIdentityInterface</code>. The other policies run before it, by IP or endpoint. See the <a href="/nette-api/pr-preview/pr-238/examples/rate-limit.html">rate limit example</a>.</p><h3 id="is-the-response-time-logged-with-the-rate-limit-or-auth-checks" tabindex="-1">Is the response time logged with the rate limit or auth checks? <a class="header-anchor" href="#is-the-response-time-logged-with-the-rate-limit-or-auth-checks" aria-label="Permalink to &quot;Is the response time logged with the rate limit or auth checks?&quot;">​</a></h3><p>Only for logged requests: the time from the start of <code>run()</code> to after the output check.</p><h3 id="can-i-add-a-step-for-example-a-request-id" tabindex="-1">Can I add a step, for example a request ID? <a class="header-anchor" href="#can-i-add-a-step-for-example-a-request-id" aria-label="Permalink to &quot;Can I add a step, for example a request ID?&quot;">​</a></h3><p>Not inside <code>run()</code>. Do it in the authorization, the handler, or a Nette <code>onRequest</code> / <code>onResponse</code> event.</p>`,38))])}const f=s(p,[["render",l]]);export{y as __pageData,f as default};
